-- Generated by graph/tools/build_capture_guard_worksets.py from sealed SQL002.
-- Preserve complete-row, duplicate and SQL-NULL evidence-guard semantics.
-- Accept exact raw and measured Hop four-comment-elided body forms only.
BEGIN;
DO $guard$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE
  p.oid='ingestion.source_graph_insert_guard()'::regprocedure
  AND md5(p.prosrc) IN ('7bf7a02ce5d39bc3ae14e5617f5595a3','3dc06905ce059260c181d7f79c42f3c8','6a7657e4685d2741814d77453466eeab','c95d9c8a5659290ec8b300c751150b80')
  AND p.provolatile='v' AND p.proparallel='u' AND NOT p.proisstrict
  AND NOT p.prosecdef AND NOT p.proleakproof AND NOT p.proretset
  AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql')
  AND p.prorettype='trigger'::regtype AND p.pronargs=0 AND p.pronargdefaults=0
  AND p.procost=100 AND p.prorows=0 AND p.prosupport=0 AND p.prokind='f'
  AND p.probin IS NULL AND p.prosqlbody IS NULL AND p.provariadic=0
  AND p.proargtypes=''::oidvector AND p.proargdefaults IS NULL
  AND p.proallargtypes IS NULL AND p.proargnames IS NULL AND p.proargmodes IS NULL
  AND p.proconfig=ARRAY['jit=off']::text[]) THEN
  RAISE EXCEPTION 'SOURCE_GRAPH_CAPTURE_WORKSET_BASELINE_DRIFT';
 END IF;
END $guard$;
CREATE OR REPLACE FUNCTION ingestion.source_graph_insert_guard() RETURNS trigger
LANGUAGE plpgsql SET jit=off AS $$
DECLARE invalid boolean; jobs text;
BEGIN
 -- Transition tables can span runs. Fence each exact run before constructing
 -- live proof, rather than rebuilding whole history for every inserted slice.
 -- Group complete inserted/live rows by the original SQL equality keys.
 -- Every live duplicate must match; NULL keys remain unmatched.
 FOR jobs IN SELECT DISTINCT run_id FROM new_evidence LOOP
  IF TG_TABLE_NAME='source_graph_record_evidence' THEN
   WITH evidence_rows AS (
    SELECT run_id,record_id,to_jsonb(e) AS payload,true AS inserted
    FROM new_evidence e WHERE e.run_id=jobs
    UNION ALL
    SELECT run_id,record_id,to_jsonb(l) AS payload,false AS inserted
    FROM ingestion.source_graph_live_record_evidence l WHERE l.run_id=jobs
   ), evidence_groups AS (
    SELECT run_id,record_id,bool_or(inserted) AS has_inserted,
     count(*) FILTER(WHERE NOT inserted) AS live_count,
     count(DISTINCT payload) AS payload_count
    FROM evidence_rows GROUP BY run_id,record_id
   )
   SELECT coalesce(bool_or(live_count=0 OR payload_count>1 OR run_id IS NULL OR record_id IS NULL),false)
   INTO invalid FROM evidence_groups WHERE has_inserted;
  ELSE
   WITH evidence_rows AS (
    SELECT run_id,record_id,identity_id,field,to_jsonb(e) AS payload,true AS inserted
    FROM new_evidence e WHERE e.run_id=jobs
    UNION ALL
    SELECT run_id,record_id,identity_id,field,to_jsonb(l) AS payload,false AS inserted
    FROM ingestion.source_graph_reference l WHERE l.run_id=jobs
   ), evidence_groups AS (
    SELECT run_id,record_id,identity_id,field,bool_or(inserted) AS has_inserted,
     count(*) FILTER(WHERE NOT inserted) AS live_count,
     count(DISTINCT payload) AS payload_count
    FROM evidence_rows GROUP BY run_id,record_id,identity_id,field
   )
   SELECT coalesce(bool_or(live_count=0 OR payload_count>1 OR run_id IS NULL OR record_id IS NULL OR identity_id IS NULL OR field IS NULL),false)
   INTO invalid FROM evidence_groups WHERE has_inserted;
  END IF;
  IF invalid OR NOT ingestion.source_graph_run_is_valid(jobs)
  THEN RAISE EXCEPTION 'INVALID_SOURCE_GRAPH_EVIDENCE'; END IF;
 END LOOP;
 RETURN NULL;
END $$;
COMMIT;
